/* Tai-Ahom Research Atlas: public metadata and optional device-local readings. */
(() => {
  'use strict';
  const D=window.ARCHIVE,I=window.RECORD_INDEX,C=window.ArchiveCore;
  const $=s=>document.querySelector(s),e=C.escapeHtml;
  const works=new Map(D.works.map(w=>[w.id,w])),index=new Map(I.map(r=>[r.id,r]));
  let readings=new Map(),lastExplore='#explore',toastTimer;
  const size=18;
  const count=n=>Number(n).toLocaleString('en-IN');
  const label=c=>c==='B'?'B · source supported':c==='C'?'C · uncertain':'Not independently reviewed';
  const badge=c=>`<span class="label ${c==='C'?'amber':c==='unreviewed'?'gray':''}">${e(label(c))}</span>`;
  const link=(url,text,cls='')=>`<a class="${cls}" href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(text)} ↗</a>`;
  const hash=(route,params={})=>{const p=new URLSearchParams();for(const[k,v]of Object.entries(params))if(v!==''&&v!=null)p.set(k,v);return '#'+route+(p.size?'?'+p.toString():'');};
  const current=()=>{const [route,query]=(location.hash.slice(1)||'home').split('?');return {route,params:Object.fromEntries(new URLSearchParams(query||''))};};
  const go=(route,params)=>{const h=hash(route,params);if(location.hash===h)render();else location.hash=h;};
  function toast(text){clearTimeout(toastTimer);$('#message').textContent=text;$('#message').hidden=false;toastTimer=setTimeout(()=>{$('#message').hidden=true;},6500);}
  function head(kicker,title,text){return `<div class="page-head"><p class="eyebrow">${e(kicker)}</p><h1>${e(title)}</h1><p>${e(text)}</p></div>`;}
  function options(values,selected,empty){return `<option value="">${e(empty)}</option>`+values.map(([v,t])=>`<option value="${e(v)}" ${v===selected?'selected':''}>${e(t)}</option>`).join('');}
  function readingNotice(){return readings.size?`<p class="notice"><strong>${count(readings.size)} readings loaded on this device.</strong> Text and English are inherited from the working editions; loading them does not certify their accuracy.</p>`:`<p class="notice">You are browsing the <strong>public source index</strong>. To search Tai-Ahom text or English meanings, <a href="#readings">load your private reading pack</a>. Manuscripts, folios and subjects are searchable now.</p>`;}
  function home(){return `<section class="hero"><div><p class="eyebrow">A living archive · source by source</p><h1>Read the record.<br><em>See the evidence.</em></h1><p class="lede">Explore Tai-Ahom manuscripts, inherited readings and research references. Every entry has a source; every uncertainty stays visible.</p><div class="actions"><a class="button" href="#explore">Explore the collection <span aria-hidden="true">→</span></a><a class="button secondary" href="#coverage">See transcription coverage</a></div></div><aside class="hero-panel"><p class="eyebrow">Inside the archive</p><h2>Sources before certainty.</h2><div class="definition"><span>Reading collections</span><strong>7</strong></div><div class="definition"><span>Indexed entry records</span><strong>4,637</strong></div><div class="definition"><span>Bar Amra entries certified A</span><strong>0</strong></div><p class="small muted">Unicode makes a reading searchable. It does not make the reading certain.</p></aside></section><div class="stats"><div class="stat"><b>3,401</b><span>Entries in six editions</span></div><div class="stat"><b>1,236</b><span>Bar Amra records</span></div><div class="stat"><b>123</b><span>Linked source files</span></div><div class="stat"><b>61</b><span>Bar Amra folio images indexed</span></div></div>${readingNotice()}<div class="section-head"><h2>Browse the texts</h2><p class="small muted">Working editions · original source links</p></div><section class="work-grid">${D.works.map(w=>`<article class="work-card"><span class="label">${e(w.kind)}</span><h3>${e(w.title)}</h3><p>${e(w.subjects.join(' · '))}</p><p><strong>${count(w.records)}</strong> indexed records<br>Source revision: ${e(w.source_date)}</p><div class="actions"><a class="button secondary" href="${hash('explore',{work:w.id})}">Explore entries →</a></div></article>`).join('')}</section><div class="method-grid"><article class="method-box"><h3>Trace the source</h3><p>Stable IDs connect each record to an edition, an analytical page or an explicit manuscript folio.</p></article><article class="method-box"><h3>Keep the layers apart</h3><p>Inherited transcriptions, English readings, editorial reconstructions and historical interpretations are distinct.</p></article><article class="method-box"><h3>Preserve what is missing</h3><p>Blank fields and unresolved gaps remain visible. A record count never stands in for complete coverage.</p></article></div>`;}
  function searchForm(route,p,placeholder){return `<form data-search="${route}"><div class="search-line"><label class="search-field"><span>Search ${route==='sources'?'source titles and categories':'Ahom, English, manuscript or subject'}</span><input type="search" name="q" value="${e(p.q||'')}" placeholder="${e(placeholder)}" autocomplete="off"></label><button class="button" type="submit">Search</button></div>${route==='explore'?`<div class="filters"><label>Text or manuscript<select name="work" aria-label="Text or manuscript">${options(D.works.map(w=>[w.id,w.title]),p.work,'All collections')}</select></label><label>Folio<input name="folio" value="${e(p.folio||'')}" placeholder="e.g. 9v" aria-describedby="folio-help"></label><label>Confidence<select name="confidence" aria-label="Confidence">${options([['B','B · source supported'],['C','C · uncertain'],['unreviewed','Not reviewed']],p.confidence,'All levels')}</select></label><label>Historical subject<select name="subject" aria-label="Historical subject">${options([...new Set(D.works.flatMap(w=>w.subjects))].sort().map(s=>[s,s]),p.subject,'All subjects')}</select></label><a class="button secondary" href="#explore">Reset</a></div><p id="folio-help" class="small muted">Folio mappings are available for Bar Amra. Other editions retain analytical-source page numbers where supplied.</p>`:`<div class="filters"><label>Category<select name="category" aria-label="Category">${options([...new Set(D.catalogue.map(s=>s.category))].sort().map(s=>[s,s.replaceAll('_',' ')]),p.category,'All categories')}</select></label><a class="button secondary" href="#sources">Reset</a></div>`}</form>`;}
  function paging(route,p,page,total){const pages=Math.max(1,Math.ceil(total/size));return `<nav class="pagination" aria-label="Results pages">${page>1?`<a class="button secondary" href="${hash(route,{...p,page:page-1})}">← Previous</a>`:'<button class="button secondary" disabled>← Previous</button>'}<span>Page ${page} of ${pages}</span>${page<pages?`<a class="button secondary" href="${hash(route,{...p,page:page+1})}">Next →</a>`:'<button class="button secondary" disabled>Next →</button>'}</nav>`;}
  function recordCard(r){const w=works.get(r.work),p=readings.get(r.id);return `<article class="record-card"><div class="record-top"><small>${e(w.title)}</small>${badge(r.confidence)}</div><h3>${r.folio?`Folio ${e(r.folio)}`:`Entry ${e(r.source_record_id)}`}</h3><span class="record-id">${e(r.id)}</span>${p?`<div class="ahom" lang="aho">${e(p.layers.inherited_transcription||'[No Ahom text supplied]')}</div><p class="english">${e(p.layers.english||'[No English reading supplied]')}</p>`:`<p class="placeholder">${r.has_ahom?'Unicode reading indexed':'No Ahom text supplied in the edition'}. ${r.has_english?'English field available in private reading pack.':'English field absent.'}</p>`}<div class="tags">${r.flags.map(f=>`<span class="tag">${e(f.replaceAll('-',' '))}</span>`).join('')}</div><div class="record-foot"><span>${r.folio?`Source reference ${e(r.source_record_id)}`:r.source_page?`Analytical-source p. ${r.source_page}`:'Folio mapping not supplied'}</span><a href="${hash('record',{id:r.id})}">View record →</a></div></article>`;}
  function explore(p){lastExplore=location.hash||'#explore';const filtered=C.filterRecords(I,D.works,readings,p),page=Math.min(Math.max(1,Number(p.page)||1),Math.max(1,Math.ceil(filtered.length/size))),w=works.get(p.work);
    return head('The reading index',w?w.title:'Explore the collection',w?w.scope:'Search source locators and subjects. With your reading pack loaded, search real Unicode Tai-Ahom and corresponding English readings.')+readingNotice()+searchForm('explore',p,'Try Bar Amra, Buddhism, 9v-10…')+`<div class="results-meta"><span role="status">${count(filtered.length)} matching records${p.folio?' · folio '+e(p.folio):''}</span><button class="button secondary" data-action="export-results">Export results</button></div><section class="record-grid">${filtered.length?filtered.slice((page-1)*size,page*size).map(recordCard).join(''):`<div class="empty"><h3>No matching records</h3><p>Try a broader query or reset the filters.${!readings.size?' Text and English meaning search need your private reading pack.':''}</p>${p.folio?'<p>A folio without an accepted reading can still appear in the <a href="#coverage">coverage register</a>.</p>':''}</div>`}</section>${paging('explore',p,page,filtered.length)}${w?`<details><summary>Source credits and edition limits</summary><p class="small">${e(w.credits)}</p><p class="small">${e(w.translation_basis)}</p><ul class="small">${w.notes.map(n=>`<li>${e(n)}</li>`).join('')}</ul>${link(w.edition_url,'Open working edition')} · ${link(w.source_url,'Open analytical source')}</details>`:''}`;
  }
  function citation(r){const w=works.get(r.work);return `${w.title}, ${r.folio?'folio '+r.folio+', source entry ': 'entry '}${r.source_record_id}${r.source_page?', analytical-source p. '+r.source_page:''}. Working edition ${w.source_date}. Tai-Ahom Research Atlas, record ${r.id}. ${label(r.confidence)}. ${w.edition_url}`;}
  function layer(title,text,ahom=false){return `<section class="layer"><div class="layer-label">${e(title)}</div><div class="${ahom?'ahom':'english'}" ${ahom?'lang="aho"':''}>${e(text||'[Not supplied]')}</div></section>`;}
  function record(p){const r=index.get(p.id);if(!r)return head('Record','Record not found','Use Explore to find a valid source identifier.');const w=works.get(r.work),v=readings.get(r.id),l=v?.layers;
    return `<div class="detail-top"><a href="${e(lastExplore)}">← Back to entries</a></div><div class="detail-layout"><article class="reading-panel"><p class="eyebrow">${e(w.title)} · inherited working edition</p><h1>${r.folio?`Folio ${e(r.folio)} · ${e(r.source_record_id)}`:`Entry ${e(r.source_record_id)}`}</h1>${badge(r.confidence)}<p class="record-id">${e(r.id)}</p>${v?`${layer(r.work==='bar-amra'?'Tai-Ahom headword · inherited transcription':'Tai-Ahom · inherited transcription',l.inherited_transcription,true)}${r.work==='bar-amra'?layer('Defining formula',l.formula,true)+layer('Assamese explanation · written in Ahom script',l.assamese_in_ahom_script,true)+layer('Punctuation',l.punctuation,true):''}${layer(r.work==='bar-amra'?'English gloss · inherited':'English reading · inherited',l.english)}${l.romanization?layer('Source romanization',l.romanization):''}${l.assamese_romanization?layer('Assamese explanation · source romanization',l.assamese_romanization):''}<p class="notice">${e(v.reading_status)}${r.headword_confidence==='A'?'<br><strong>The A rating applies to the headword only. This complete entry is not certified A.</strong>':''}</p>${v.notes.length?`<h2>Editorial notes from the edition</h2><ul class="notes">${v.notes.map(n=>`<li>${e(n)}</li>`).join('')}</ul>`:''}<details><summary>Editorial reconstructions and interpretations</summary><p class="small">Editorial reconstruction: ${e(l.editorial_reconstruction||'None added in this release.')}</p><p class="small">Historical interpretation: ${e(l.interpretation||'None attached to this record.')}</p></details><details><summary>Original source record and alternatives</summary><p class="small muted">Preserved as supplied. Legacy-font strings are evidence, not Unicode search fields.</p><pre class="raw">${e(JSON.stringify(v.source_record,null,2))}</pre></details>`:`<div class="notice"><p>The source locator is public. The inherited reading and English text are held in your private research pack pending reproduction permission.</p><a class="button" href="#readings">Load readings on this device</a></div><p class="small">No reconstructed reading has been substituted for the withheld text.</p>`}<h2>Cite this record</h2><p class="citation">${e(citation(r))}</p><button class="button secondary" data-action="copy-citation" data-id="${e(r.id)}">Copy reference</button></article><aside class="side-panel"><h2>Source & review</h2><dl><dt>Project identifier</dt><dd>${e(w.identifier)}</dd><dt>Original record identifier</dt><dd>${e(r.source_record_id)}</dd><dt>Folio</dt><dd>${e(r.folio||'Not supplied')}</dd>${r.image?`<dt>Supplied image / facsimile page</dt><dd>${r.image} / ${r.facsimile_page}</dd>`:''}<dt>Analytical-source page</dt><dd>${e(r.source_page||'Not supplied; do not infer a folio')}</dd><dt>Complete-entry confidence</dt><dd>${e(label(r.confidence))}</dd>${r.headword_confidence?`<dt>Headword confidence only</dt><dd>${e(r.headword_confidence)}</dd>`:''}<dt>Source revision</dt><dd>${e(w.source_date)}</dd></dl><p>${e(w.credits)}</p><div class="actions">${link(w.edition_url,'Working edition','button secondary')}${link(w.source_url,'Source','button secondary')}</div><p class="small muted">Linked files retain their existing access permissions.</p>${r.work==='bar-amra'?'<p><a href="#coverage">View the coverage register →</a></p>':''}</aside></div>`;
  }
  function sources(p){let rows=D.catalogue.filter(s=>(!p.category||s.category===p.category)&&C.matches(p.q,[s.title,s.filename,s.category]));const page=Math.min(Math.max(1,Number(p.page)||1),Math.max(1,Math.ceil(rows.length/size)));
    return head('Bibliography & source catalogue','Follow the source.','The 14 October catalogue records 118 PDFs and three other files. This release adds links to the revised Bar Amra review and mobile edition; original files remain in Drive.')+searchForm('sources',p,'Try Morey, religion, Buranji, calendar…')+`<p class="results-meta" role="status">${count(rows.length)} source links · access may be required</p><section class="source-list">${rows.slice((page-1)*size,page*size).map(s=>`<article class="source-row"><div><h3>${e(s.title)}</h3><p>${e(s.category.replaceAll('_',' '))} · ${e(s.format==='application/pdf'?'PDF':s.format.split('/').pop())}</p><p>Catalogued ${e(s.catalogued_on)} · linked, not redistributed</p></div>${link(s.url,'Open source','button secondary')}</article>`).join('')||'<div class="empty">No matching source titles. Try a shorter query.</div>'}</section>${paging('sources',p,page,rows.length)}`;
  }
  function coverage(p){const c=D.coverage,s=c.summary,rows=c.gaps.filter(g=>p.all==='1'||g.status==='unresolved');return head('Bar Amra · revision of 19 October 2026','Make the gaps visible.','Recovered records are not the same as complete transcription. The folio register keeps image numbering, source entry IDs and uncertainty separate.')+`<div class="coverage-stats"><div class="coverage-stat"><b>1,236</b><span>Recovered entry records</span></div><div class="coverage-stat"><b>55</b><span>Numbered IDs without accepted readings</span></div><div class="coverage-stat"><b>4</b><span>Whole folios untranscribed</span></div><div class="coverage-stat"><b>0</b><span>Complete entries certified A</span></div></div><p class="notice"><strong>819 B records · 417 C records.</strong> Four headwords have selected visual checks; this does not certify their complete entries. Four of the six additions are partial records.</p><h2>The 61 supplied folio images</h2><p class="small muted">A green cell means some records were recovered, not that the folio is complete. Select a folio to inspect its indexed records.</p><div class="legend"><span>Green · recovered records</span><span>Gold · known numbered gaps</span><span>Brown · no accepted records</span></div><div class="folio-grid">${c.folios.map(f=>`<a class="folio ${!f.recovered_entries?'missing':f.missing_numbered_entries.length?'gap':''}" href="${hash('explore',{work:'bar-amra',folio:f.folio})}" aria-label="Folio ${f.folio}, ${f.recovered_entries} recovered records, ${f.missing_numbered_entries.length} numbered gaps"><span>${e(f.folio)}</span><small>${f.recovered_entries?count(f.recovered_entries)+' records':'untranscribed'}</small></a>`).join('')}</div><div class="section-head"><h2>${p.all==='1'?'All 65 tracked targets':'59 outstanding targets'}</h2><a class="small" href="${hash('coverage',p.all==='1'?{}:{all:1})}">${p.all==='1'?'Show outstanding only':'Include the six added records'}</a></div><p class="small muted">Four whole-folio gaps plus 55 numbered entry IDs remain open. No entry total is invented for an untranscribed folio. Source entry numbers are not physical line numbers.</p><div class="table-wrap"><table><caption class="sr-only">Bar Amra transcription gap register</caption><thead><tr><th scope="col">Target</th><th scope="col">Type</th><th scope="col">Image</th><th scope="col">Facsimile page</th><th scope="col">Status</th></tr></thead><tbody>${rows.map(g=>`<tr><td>${index.has('bar-amra:'+g.id)?`<a href="${hash('record',{id:'bar-amra:'+g.id})}">${e(g.id)}</a>`:e(g.id)}</td><td>${g.kind==='whole_folio'?'Whole folio':'Numbered entry'}</td><td>${g.image}</td><td>${g.facsimile_pdf_page}</td><td>${e(g.status.replaceAll('_',' '))}</td></tr>`).join('')}</tbody></table></div><details><summary>What the image comparison established</summary><p class="small">The prior review matched 1r to EAP373/26/2 canvas 3 and 10r to canvas 21. It did not establish replacement photographs for 26r or 26v. The EAP sequence has 117 images; its image numbers must not be substituted for manuscript foliation.</p></details><p>${link('https://drive.google.com/file/d/1OfhHTd1zTW8gK5cZE5NzNP1Zkgrz7tLS/view','Read the evidence review')}</p>`;}
  function research(){return head('Historical subjects & interpretation','A question is not a conclusion.','The earlier Lengdon–Nimi dossier is retained as a separate interpretive layer. Its source observations, comparisons and hypotheses are labelled; they are not transcription certifications.')+`<p class="notice">${e(D.research.status)}</p><div class="research-grid">${D.research.claims.map(c=>`<article class="research-card"><span class="label ${c.category==='hypothesis'?'amber':''}">${e(c.label)}</span><h2>${e(c.title)}</h2><p>${e(c.text)}</p><p class="small muted">${e(c.locator)}</p><p class="small">${e(c.review)}</p><div class="actions">${c.sources.map(id=>{const s=D.research.sources.find(s=>s.id===id);return s?link(s.url,s.short):'';}).join(' ')}</div></article>`).join('')}</div>`;}
  function method(){return head('Editorial method','Separate the evidence layers.','This release restores structure and searchability. It does not claim new translations, a complete critical edition or independent specialist certification.')+`<div class="method-grid"><section class="method-box"><h3>1. Original source</h3><p>A manuscript image or printed witness is an evidence object. The public archive links to it; photographs are not Unicode transcriptions.</p></section><section class="method-box"><h3>2. Inherited reading</h3><p>A scholarly transcription and its English rendering are credited separately. Encoding repair retains supplied uncertainty and alternatives.</p></section><section class="method-box"><h3>3. Editorial claim</h3><p>Reconstructions and historical interpretations occupy distinct fields. This release adds no reconstructed characters or new translations.</p></section></div><div class="prose"><h2>How to read confidence</h2><ul><li><strong>B, Bar Amra:</strong> supported by a named source; not a complete independent certification of every manuscript glyph.</li><li><strong>C, Bar Amra:</strong> partial coverage, unresolved reading or disagreement.</li><li><strong>A, headword only:</strong> selected visual checks recorded for four headwords. No complete entry is rated A.</li><li><strong>Not independently reviewed:</strong> six other working editions retain their source warnings. They have not been assigned the Bar Amra B/C rubric.</li></ul><h2>What Unicode validation means</h2><p>All imported Ahom reading fields were checked for private-use and replacement characters. Source gap markers remain visible, including five <code>[unresolved-50]</code> occurrences in Ma Likha Lit. Encoding validity does not settle a reading or translation.</p><h2>Identifiers and subjects</h2><p>TAH identifiers are local project IDs, not archival shelfmarks. Source entry IDs remain unchanged. Analytical-source PDF pages are never labelled as manuscript folios. Subject tags describe the work at collection level; they do not assert that each individual entry contains that subject.</p><h2>Publication & reproduction</h2><p>Public files contain code, bibliographical metadata, locators and coverage summaries. Complete inherited readings and scans require a documented reproduction basis before public release. A Drive link preserves its existing access settings.</p>${D.rights.sources.map(r=>`<details><summary>${e(r.title)} · ${e(r.status.replaceAll('-',' '))}</summary><p>${e(r.basis)}</p>${link(r.evidence_url,'Rights evidence or source')}</details>`).join('')}<h2>Source preservation</h2><p>The original Drive collection and the earlier <code>import/ahom-atlas</code> branch are preserved. The private reading package retains original master records alongside normalized search fields, with source archive fingerprints and reproducible import scripts.</p><p>Technical checks cover record counts, identifiers, source-field preservation, confidence totals, gaps, Unicode and search behavior. They do not substitute for specialist manuscript collation.</p></div>`;}
  function readingsPage(){return head('Your research copy','Read privately. Search fully.','Load the supplied reading pack to search Tai-Ahom text and English meanings. The file is processed on this device and is never uploaded by this interface.')+`<section class="upload-box"><h2>${readings.size?count(readings.size)+' readings available':'Load a reading pack'}</h2><p class="small muted">Choose <strong>Tai_Ahom_Reading_Pack_20261026.json</strong> from the downloaded research package. The offline edition already includes these readings.</p><label for="pack-file">Reading pack JSON file</label><br><input id="pack-file" type="file" accept="application/json,.json"><br><label><input id="remember-pack" type="checkbox">Keep readings on this device for later visits</label><p class="small muted">Leave this unchecked on a shared device. Browser storage can be cleared by the browser; keep your downloaded copy.</p><div class="actions"><a class="button" href="#explore">Explore entries →</a>${readings.size?'<button class="button secondary" data-action="unload">Unload readings</button>':''}</div><p id="import-status" class="small" role="status"></p></section><div class="prose"><h2>What is in the research pack</h2><p>All 3,401 numbered records from the six Unicode editions and all 1,236 records from the Bar Amra revision. Missing readings, placeholders, source notes and alternate readings are retained. This is a structured copy of the available working texts, not a newly certified edition.</p><h2>Keeping private content private</h2><p>The public GitHub repository does not include the reading pack, manuscript scans or third-party transcription files. The downloadable package separates the publishable repository from the private reading directory. Do not upload the private directory to a public repository.</p><p>The archive has no analytics, remote database or upload endpoint. Optional remembered readings use this browser’s local storage database. Unload removes that saved copy.</p></div>`;}
  function render(){const {route,params:p}=current();const pages={home,explore,sources,coverage,record,research,method,readings:readingsPage};$('#main').innerHTML=(pages[route]||home)(p);document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));$('#pack-status').innerHTML=readings.size?`${count(readings.size)} readings loaded`:'Load readings <span aria-hidden="true">↗</span>';document.title=(route==='home'?'':({explore:'Explore',sources:'Sources',coverage:'Coverage',record:'Record',research:'Research',method:'Method',readings:'Local readings'}[route]||'')+' · ')+'Tai-Ahom Research Atlas';}
  async function database(){return new Promise((resolve,reject)=>{const request=indexedDB.open('tai-ahom-reading-cache-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('packs');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
  async function cachePack(mode,value){const db=await database();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('packs',mode==='get'?'readonly':'readwrite'),store=tx.objectStore('packs');let request=mode==='get'?store.get('current'):mode==='set'?store.put(value,'current'):store.delete('current');tx.oncomplete=()=>resolve(request.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}finally{db.close();}}
  document.addEventListener('submit',event=>{const form=event.target.closest('form[data-search]');if(!form)return;event.preventDefault();go(form.dataset.search,Object.fromEntries(new FormData(form)));});
  document.addEventListener('change',async event=>{
    if(event.target.matches('form[data-search] select,form[data-search] input[name=folio]')){const form=event.target.closest('form');go(form.dataset.search,Object.fromEntries(new FormData(form)));return;}
    if(event.target.id!=='pack-file')return;
    const f=event.target.files[0];if(!f)return;const status=$('#import-status');status.textContent='Checking reading pack…';
    try{if(f.size>20*1024*1024)throw new Error('This file exceeds the 20 MB reading-pack limit.');const pack=JSON.parse(await f.text());const rows=C.validatePack(pack,I);let saved=false;if($('#remember-pack').checked){await cachePack('set',pack);saved=true;}else{await cachePack('delete').catch(()=>{});}readings=new Map(rows.map(r=>[r.id,r]));render();toast(`${count(rows.length)} readings loaded${saved?' and kept on this device': ' for this session'}.`);}catch(err){status.textContent='Import failed: '+err.message;toast('The existing readings were not changed.');}
  });
  document.addEventListener('click',async event=>{if(event.target.closest('.skip')){event.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}const b=event.target.closest('[data-action]');if(!b)return;
    if(b.dataset.action==='copy-citation'){try{await navigator.clipboard.writeText(citation(index.get(b.dataset.id)));toast('Reference copied.');}catch{toast('Clipboard unavailable. Select and copy the reference shown above.');}}
    if(b.dataset.action==='unload'){try{await cachePack('delete');readings.clear();render();toast('Saved readings removed from this browser.');}catch{toast('Could not clear browser storage. No saved data was changed.');}}
    if(b.dataset.action==='export-results'){const rows=C.filterRecords(I,D.works,readings,current().params).map(r=>readings.get(r.id)||r);const blob=new Blob([JSON.stringify({exported:new Date().toISOString(),notice:'Research export; source rights and review limits remain unchanged.',records:rows},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Tai_Ahom_Search_'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${count(rows.length)} results exported.`);}
  });
  window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
  // Retire the old reader service worker if the previous build was once served at this exact scope.
  if('serviceWorker' in navigator){navigator.serviceWorker.getRegistrations().then(regs=>{for(const r of regs)if(r.scope===new URL('./',location.href).href)r.unregister();}).catch(()=>{});}
  render();
  (async()=>{try{const pack=window.PRIVATE_READING_PACK||await cachePack('get');if(pack){const rows=C.validatePack(pack,I);readings=new Map(rows.map(r=>[r.id,r]));render();}}catch(err){toast('Saved readings could not be loaded. You can import the reading pack again.');}})();
})();
